const header=document.querySelector('header'),menu=document.querySelector('.menu-toggle'),nav=document.querySelector('nav');
function updateHeader(){header.classList.toggle('solid',scrollY>30)}
addEventListener('scroll',updateHeader,{passive:true});updateHeader();
function closeMenu(){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');nav.querySelectorAll('details').forEach(d=>d.open=false)}
menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation')});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));
nav.querySelectorAll('details').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)nav.querySelectorAll('details').forEach(other=>{if(other!==d)other.open=false})}));
document.addEventListener('click',e=>{if(!header.contains(e.target))closeMenu()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const opened=nav.querySelector('details[open]');if(opened){opened.open=false;opened.querySelector('summary').focus()}else if(nav.classList.contains('open')){closeMenu();menu.focus()}}});
nav.addEventListener('focusout',()=>setTimeout(()=>{if(!nav.contains(document.activeElement))nav.querySelectorAll('details').forEach(d=>d.open=false)},0));
document.querySelector('#credits-open').addEventListener('click',()=>document.querySelector('#credits-dialog').showModal());
document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()}})});
if(!matchMedia('(prefers-reduced-motion: reduce)').matches&&'IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.08});document.querySelectorAll('.about-grid,.section-heading,.service,.project').forEach(element=>{element.classList.add('reveal');observer.observe(element)})}
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));let count=0;document.querySelectorAll('.listing .project').forEach(p=>{p.hidden=button.dataset.filter!=='all'&&p.dataset.country!==button.dataset.filter;if(!p.hidden)count++});document.querySelector('#filter-status').textContent=`${count} project placeholders shown.`}));
const form=document.querySelector('#contact-form');
if(form){const params=new URLSearchParams(location.search);for(const name of ['country','interest'])if(params.has(name))form.elements[name].value=params.get(name);if(params.has('project'))form.elements.message.value=`I would like to discuss ${params.get('project')}.`;
form.addEventListener('submit',async e=>{e.preventDefault();if(!form.reportValidity())return;const button=form.querySelector('button'),status=document.querySelector('#form-status');button.disabled=true;button.textContent='SENDING…';status.className='';status.textContent='Submitting your enquiry…';form.setAttribute('aria-busy','true');try{const response=await fetch('/api/contact',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(form))),signal:AbortSignal.timeout(15000)});if(!response.ok)throw Error('Delivery is currently unavailable. Please email hashim@globalmino.com or call +353 85 159 0630. Your enquiry has not been sent.');status.className='success';status.textContent='Your enquiry has been received. Thank you for contacting Global Mino.';form.reset()}catch(error){status.className='error';status.textContent=error.message.startsWith('Delivery')?error.message:'Your enquiry could not be sent. Please try again or email hashim@globalmino.com. Your message remains in the form.'}finally{button.disabled=false;button.innerHTML='SEND ENQUIRY <span>↗</span>';form.removeAttribute('aria-busy')}})}
